package com.yihe.framework.ehr;
import java.util.*;
import java.time.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;
@Service
public class FilingWorkbenchService {
 final EhrRepository db;final EhrService ehr;final OccupationalArchiveService occupational;final GeneralArchiveService general;
 public FilingWorkbenchService(EhrRepository db,EhrService ehr,@org.springframework.beans.factory.annotation.Qualifier("occupationalArchiveService") OccupationalArchiveService occupational,GeneralArchiveService general){this.db=db;this.ehr=ehr;this.occupational=occupational;this.general=general;}
 OccupationalArchiveService service(String kind){require(Arrays.asList("occupational","general").contains(kind),422,"档案类型无效");return kind.equals("general")?general:occupational;}
 public Map<String,Object> list(EhrActor a,Map<String,String> q){require(!a.mobile,403,"个人端无办理工作台权限");String kind=q.getOrDefault("kind","occupational"),table=service(kind).table();
 String base="SELECT p.*,COALESCE(v.document_status,'unfiled') filingStatus,COALESCE(v.revision,0) filingVersion,JSON_UNQUOTE(JSON_EXTRACT(v.document_json,'$.dueDate')) dueDate,v.created_at filingUpdatedAt FROM ("+ehr.projection()+") p LEFT JOIN "+table+" v ON v.scope_code=? AND v.data_mode=? AND v.record_id=p.id AND v.revision=(SELECT MAX(v2.revision) FROM "+table+" v2 WHERE v2.scope_code=v.scope_code AND v2.data_mode=v.data_mode AND v2.record_id=v.record_id)";
 Object[] scope={a.scope,a.mode,a.scope,a.mode};Map<String,Object> stats=db.one("SELECT COUNT(*) total,SUM(filingStatus='unfiled') pending,SUM(filingStatus='pending_employee') employeePending,SUM(filingStatus='employee_confirmed') doctorPending,SUM(filingStatus='archived') completed,SUM(filingStatus='draft') drafts,SUM(filingStatus NOT IN ('unfiled','archived') AND dueDate REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND dueDate BETWEEN DATE(CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+08:00')) AND DATE_ADD(DATE(CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+08:00')),INTERVAL 7 DAY)) dueSoon,SUM(filingStatus IN ('draft','pending_employee','employee_confirmed','reviewed')) inProgress FROM ("+base+") x",scope);
 String outer="SELECT * FROM ("+base+") x WHERE 1=1";List<Object> args=new ArrayList<>(Arrays.asList(scope));String search=q.getOrDefault("search","").trim();if(!search.isEmpty()){outer+=" AND (name LIKE ? ESCAPE '!' OR code LIKE ? ESCAPE '!' OR team LIKE ? ESCAPE '!')";for(int i=0;i<3;i++)args.add("%"+like(search)+"%");}
 String state=q.getOrDefault("state","pending");require(Arrays.asList("pending","progress","completed","all").contains(state),422,"任务状态无效");if(state.equals("pending"))outer+=" AND filingStatus IN ('unfiled','draft','pending_employee')";if(state.equals("progress"))outer+=" AND filingStatus IN ('draft','pending_employee','employee_confirmed','reviewed')";if(state.equals("completed"))outer+=" AND filingStatus='archived'";
 String status=q.getOrDefault("status","");if(!status.isEmpty()){require(Arrays.asList("unfiled","draft","pending_employee","employee_confirmed","reviewed","archived","due").contains(status),422,"办理状态无效");if(status.equals("due"))outer+=" AND dueDate BETWEEN DATE(CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+08:00')) AND DATE_ADD(DATE(CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+08:00')),INTERVAL 7 DAY) AND filingStatus<>'archived'";else{outer+=" AND filingStatus=?";args.add(status);}}
 int page=bounded(q.get("page"),1,1,100000),limit=bounded(q.get("limit"),10,1,50);long total=db.count("SELECT COUNT(*) FROM ("+outer+") n",args.toArray());args.add(limit);args.add((page-1)*limit);return map("items",db.all(outer+" ORDER BY created DESC,id DESC LIMIT ? OFFSET ?",args.toArray()),"total",total,"page",page,"limit",limit,"counts",stats,"kind",kind);}
 public Map<String,Object> detail(EhrActor a,String record,String kind,Integer version){return service(kind).detail(a,record,version);}
 @SuppressWarnings("unchecked") public Map<String,Object> proposal(EhrActor a,String record,String kind){Map<String,Object> d=detail(a,record,kind,null),facts=(Map<String,Object>)d.get("employee"),document=new LinkedHashMap<>((Map<String,Object>)d.get("document"));List<Object> changes=new ArrayList<>();for(Object item:(List<?>)facts.get("occupationalFields")){Map<?,?> f=(Map<?,?>)item;String key=str(f.get("fieldKey")),target=key.equals("protection_measures")?"protection":key.equals("exposure_start")?"exposureSince":key.equals("occupational_history")?"exposureNotes":"";String value=str(f.get("value"));if(target.isEmpty()||!str(document.get(target)).isEmpty()||value.isEmpty())continue;if(target.equals("exposureSince"))try{LocalDate.parse(value);}catch(Exception invalid){continue;}if(value.length()>1500)continue;document.put(target,value);changes.add(map("field",target,"value",value,"reportId",f.get("reportId"),"revision",f.get("revision"),"page",f.get("page"),"sourceId",f.get("sourceId"),"reviewStatus",f.get("reviewStatus")));}return map("document",document,"changes",changes,"sourceDigest",d.get("sourceDigest"),"expectedRevision",d.get("currentVersion"));}
 @Transactional public Map<String,Object> act(EhrActor a,String record,String kind,Map<String,Object> body){return service(kind).act(a,record,body);}
 @Transactional @SuppressWarnings("unchecked") public Map<String,Object> batch(EhrActor a,Map<String,Object> body){require(a.doctor&&!a.mobile,403,"仅授权医生可批量填写");String kind=text(body,"kind");OccupationalArchiveService s=service(kind);Object raw=body.get("items");require(raw instanceof List&&((List<?>)raw).size()>0&&((List<?>)raw).size()<=20,422,"每批请选择1至20份");Set<String> ids=new HashSet<>();for(Object value:(List<?>)raw){require(value instanceof Map,422,"批量参数无效");require(ids.add(text((Map<String,Object>)value,"recordId")),422,"不可重复选择档案");}List<Object> results=new ArrayList<>();for(Object value:(List<?>)raw){require(value instanceof Map,422,"批量参数无效");Map<String,Object> item=new LinkedHashMap<>((Map<String,Object>)value);String record=text(item,"recordId");ehr.profile(a,record,true);Map<String,Object> d=s.detail(a,record,null);require(Arrays.asList("unfiled","draft").contains(str(d.get("status"))),409,"批量填写仅处理未填写或草稿档案");Map<String,Object> proposed=proposal(a,record,kind);item.put("document",proposed.get("document"));item.put("action","save");item.put("note","批量据原报告字段填写草稿；"+text(body,"note"));results.add(s.act(a,record,item));}return map("count",results.size(),"items",results);}
}
